function Dialog({title,sub,children,onClose,wide=false}:{title:string;sub?:string;children:React.ReactNode;onClose:()=>void;wide?:boolean}){
 const panel=useRef<HTMLElement>(null),close=useRef(onClose);close.current=onClose;
 useEffect(()=>{const previous=document.activeElement as HTMLElement|null;const old=document.body.style.overflow;document.body.style.overflow="hidden";const focusable=()=>Array.from(panel.current?.querySelectorAll<HTMLElement>('button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex="0"]')??[]).filter(x=>x.getClientRects().length>0);const timer=setTimeout(()=>{const first=panel.current?.querySelector<HTMLElement>('input,select,textarea');(first??focusable()[0])?.focus();},20);const listener=(e:KeyboardEvent)=>{if(e.key==="Escape")close.current();if(e.key==="Tab"){const items=focusable();if(!items.length)return;const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};document.addEventListener("keydown",listener);return()=>{clearTimeout(timer);document.removeEventListener("keydown",listener);document.body.style.overflow=old;previous?.focus();};},[]);
 return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><section ref={panel} className={`modal ${wide?"modal-wide":""}`} role="dialog" aria-modal="true" aria-label={title}><header><div><h2>{title}</h2>{sub&&<p>{sub}</p>}</div><button className="icon-button" onClick={onClose} aria-label="Đóng"><X size={21}/></button></header>{children}</section></div>;
}
type Field={key:string;label:string;type?:string;options?:{value:string;label:string}[];required?:boolean;placeholder?:string;min?:string;max?:string;hint?:string};
