 useEffect(()=>{if(!data?.me.id)return;const refresh=()=>{if(document.visibilityState==="visible")void load();};const timer=setInterval(refresh,20000);window.addEventListener("focus",refresh);document.addEventListener("visibilitychange",refresh);return()=>{clearInterval(timer);window.removeEventListener("focus",refresh);document.removeEventListener("visibilitychange",refresh);};},[data?.me.id,load]);
