function ExamDialog({data,visit,onClose,mutate}:{data:AppData;visit:Visit;onClose:()=>void;mutate:(v:Record<string,unknown>)=>Promise<boolean>}){
 const r=data.records.find(r=>r.visitId===visit.id),a=data.appointments.find(a=>a.id===visit.appointmentId),p=data.patients.find(p=>p.id===a?.patientId);
 const [rx,setRx]=useState((r?.rx??[]).map(x=>({...x}))),[busy,setBusy]=useState(false),[finishing,setFinishing]=useState(false);
 async function submit(form:HTMLFormElement,finish:boolean){if(finish&&!finishing){setFinishing(true);return;}const values=Object.fromEntries(new FormData(form).entries());setBusy(true);try{const ok=await mutate({action:finish?"finishExam":"saveExam",visitId:visit.id,...values,rx:rx.map(x=>({medicineId:x.medicineId,dose:x.dose,times:Number(x.times),days:Number(x.days),quantity:Number(x.quantity),instructions:x.instructions}))});if(ok&&finish)onClose();else if(ok)setFinishing(false);}finally{setBusy(false);}}
 return <Dialog title="Phiếu khám bệnh" sub={`${p?.name} · ${a?.id} · Số thứ tự ${visit.queue}`} wide onClose={onClose}><form onSubmit={e=>{e.preventDefault();const action=(e.nativeEvent as SubmitEvent).submitter?.getAttribute("value");void submit(e.currentTarget,action==="finish");}}><div className="exam-content"><div className="patient-banner"><span className="avatar mint">{initials(p?.name??"BN")}</span><div><strong>{p?.name}</strong><small>{p?.gender} · {p?.birth&&displayDate(p.birth)} · {p?.phone}</small></div><Badge status="examining"/></div><div className="exam-history"><p><b>Tiền sử:</b> {p?.history||"Chưa ghi nhận"}</p><p className="allergy-text"><AlertCircle size={15}/><b>Dị ứng:</b> {p?.allergies||"Chưa ghi nhận"}</p></div><h3 className="section-title"><Stethoscope size={18}/> Thông tin thăm khám</h3><div className="form-grid">{[{key:"symptoms",label:"Triệu chứng",placeholder:"Lý do đến khám và triệu chứng…"},{key:"findings",label:"Kết quả thăm khám",placeholder:"Ghi nhận khám lâm sàng…"},{key:"diagnosis",label:"Chẩn đoán",placeholder:"Chẩn đoán của bác sĩ…"},{key:"treatment",label:"Hướng điều trị",placeholder:"Kế hoạch và hướng dẫn điều trị…"}].map(f=><label key={f.key}><span>{f.label} <em>*</em></span><textarea name={f.key} rows={3} placeholder={f.placeholder} defaultValue={r?.[f.key as keyof MedicalRecord] as string??""}/></label>)}</div><div className="section-heading"><h3 className="section-title"><Pill size={18}/> Đơn thuốc <span className="muted">(nếu có)</span></h3><button type="button" className="text-link" onClick={()=>{const m=data.medicines.find(m=>m.active);if(m)setRx([...rx,{medicineId:m.id,name:m.name,unit:m.unit,dose:"1 viên",times:1,days:7,quantity:7,instructions:""}]);}}><Plus size={16}/> Thêm thuốc</button></div>{rx.length?<div className="rx-editor">{rx.map((line,i)=><div className="rx-line" key={i}><div className="rx-number">{i+1}</div><div className="rx-line-fields"><label className="full-width"><span>Tên thuốc</span><select value={line.medicineId} onChange={e=>{const m=data.medicines.find(m=>m.id===e.target.value)!;setRx(rx.map((x,j)=>i===j?{...x,medicineId:m.id,name:m.name,unit:m.unit}:x));}}>{data.medicines.filter(m=>m.active).map(m=><option key={m.id} value={m.id}>{m.name}</option>)}</select></label>{[{key:"dose",label:"Liều mỗi lần",type:"text"},{key:"times",label:"Lần/ngày",type:"number"},{key:"days",label:"Số ngày",type:"number"},{key:"quantity",label:"Số lượng",type:"number"}].map(f=><label key={f.key}><span>{f.label}</span><input type={f.type} min="1" value={line[f.key as keyof typeof line]} required onChange={e=>setRx(rx.map((x,j)=>j===i?{...x,[f.key]:f.type==="number"?Number(e.target.value):e.target.value}:x))}/></label>)}<label className="full-width"><span>Hướng dẫn sử dụng <em>*</em></span><input required={finishing} value={line.instructions} onChange={e=>setRx(rx.map((x,j)=>j===i?{...x,instructions:e.target.value}:x))} placeholder="Thời điểm dùng thuốc và lưu ý…"/></label></div><button type="button" className="icon-button danger" aria-label={`Xóa thuốc ${i+1}`} onClick={()=>setRx(rx.filter((_,j)=>j!==i))}><Trash2 size={17}/></button></div>)}</div>:<div className="empty-rx">Chưa có thuốc. Có thể hoàn tất lượt khám mà không kê đơn.</div>}<h3 className="section-title"><CalendarDays size={18}/> Đề nghị tái khám</h3><div className="form-grid"><label><span>Ngày đề nghị</span><input type="date" name="followupDate" min={localDate()} defaultValue={r?.followupDate??""}/></label><label><span>Lời dặn</span><input name="followupNotes" defaultValue={r?.followupNotes??""} placeholder="Hướng dẫn theo dõi sau khám…"/></label></div><p className="field-note">Ngày đề nghị chưa phải lịch hẹn đã giữ chỗ. Bệnh nhân hoặc lễ tân cần đặt ca và xác nhận lịch.</p>{finishing&&<div className="confirm-publish"><ShieldCheck size={22}/><p><strong>Công bố kết quả cho bệnh nhân?</strong><br/>Sau khi hoàn tất, phiếu khám không được sửa trực tiếp. Kiểm tra lại và nhấn “Xác nhận hoàn tất”.</p><button type="button" className="text-link" onClick={()=>setFinishing(false)}>Kiểm tra lại</button></div>}</div><footer className="modal-footer"><button type="button" className="button secondary" onClick={onClose}>Đóng</button><button type="submit" value="save" formNoValidate className="button secondary" disabled={busy}>Lưu bản nháp</button><button type="submit" value="finish" className="button primary" disabled={busy}>{busy?<Loader2 size={17} className="spin"/>:<CheckCheck size={18}/>} {finishing?"Xác nhận hoàn tất":"Hoàn tất khám"}</button></footer></form></Dialog>;
}
function RecordDialog({record:r,data:d,onClose,onRebook}:{record:MedicalRecord;data:AppData;onClose:()=>void;onRebook:()=>void}){const v=d.visits.find(v=>v.id===r.visitId),a=d.appointments.find(a=>a.id===v?.appointmentId),p=d.patients.find(p=>p.id===a?.patientId),doc=d.doctors.find(doc=>doc.id===v?.doctorId),sh=d.shifts.find(s=>s.id===a?.shiftId);return <Dialog title="Kết quả khám bệnh" sub={`${p?.name??""} · ${sh?displayDate(sh.date):""} · ${doc?.title??""} ${doc?.name??""}`} wide onClose={onClose}><div className="record-content"><span className={`badge ${r.publishedAt?"green":"amber"}`}>{r.publishedAt?"Đã công bố":"Phiếu nháp · Chưa công bố"}</span><div className="record-fields">{[{label:"Triệu chứng",value:r.symptoms},{label:"Kết quả thăm khám",value:r.findings},{label:"Chẩn đoán",value:r.diagnosis},{label:"Hướng điều trị",value:r.treatment}].map(f=><section key={f.label}><h3>{f.label}</h3><p>{f.value||"Chưa ghi nhận"}</p></section>)}</div><h3 className="section-title"><Pill size={18}/> Đơn thuốc</h3>{r.rx.length?<div className="table-scroll"><table className="data-table prescription-table"><thead><tr><th>THUỐC</th><th>LIỀU DÙNG</th><th>SỐ LƯỢNG</th><th>HƯỚNG DẪN</th></tr></thead><tbody>{r.rx.map((m,i)=><tr key={i}><td><strong>{m.name}</strong><small className="cell-sub">{m.unit}</small></td><td>{m.dose} × {m.times} lần/ngày<small className="cell-sub">Trong {m.days} ngày</small></td><td>{m.quantity} {m.unit.toLowerCase()}</td><td>{m.instructions||"Theo chỉ định của bác sĩ"}</td></tr>)}</tbody></table></div>:<div className="empty-rx">Lần khám này không kê thuốc.</div>}{r.followupDate&&<div className="followup-card"><span className="stat-icon mint"><CalendarDays size={22}/></span><div><h3>Đề nghị tái khám ngày {displayDate(r.followupDate)}</h3><p>{r.followupNotes||"Theo hướng dẫn của bác sĩ."}</p><small>Cần chọn ca còn trống để xác nhận lịch khám.</small></div>{d.me.role==="patient"&&<button className="button primary" onClick={onRebook}>Đặt lịch <ArrowRight size={16}/></button>}</div>}</div><footer className="modal-footer"><button className="button secondary" onClick={onClose}>Đóng</button></footer></Dialog>;}
function Reports({data:d,from,to}:{data:AppData;from:string;to:string}){if(from>to)return <div className="info-strip"><AlertCircle size={18}/>Ngày bắt đầu phải trước ngày kết thúc.</div>;const appointments=d.appointments.filter(a=>{const s=d.shifts.find(s=>s.id===a.shiftId);return s&&s.date>=from&&s.date<=to;});const unique=new Set(appointments.filter(a=>!["cancelled","rejected"].includes(a.status)).map(a=>a.patientId));const items=[{label:"Bệnh nhân duy nhất",count:unique.size,icon:Users},{label:"Tổng số lịch hẹn",count:appointments.length,icon:CalendarDays},{label:"Lượt khám hoàn tất",count:d.visits.filter(v=>v.status==="completed"&&appointments.some(a=>a.id===v.appointmentId)).length,icon:CheckCheck},{label:"Lịch hủy / từ chối",count:appointments.filter(a=>["cancelled","rejected"].includes(a.status)).length,icon:X}];return <><div className="stats-grid">{items.map(it=><div className="stat-card" key={it.label}><div className="stat-top"><span>{it.label}</span><span className="stat-icon mint"><it.icon size={20}/></span></div><b>{it.count}</b><div className="stat-note">Trong khoảng thời gian đã chọn</div></div>)}</div><div className="report-columns"><section className="card"><div className="card-heading"><h2>Phân bổ trạng thái lịch hẹn</h2></div><div className="status-bars">{Object.entries(statuses).filter(([key])=>["pending","confirmed","received","cancelled","rejected"].includes(key)).map(([key,info])=>{const count=appointments.filter(a=>a.status===key).length;return <div key={key}><span className={`badge ${info.class}`}>{info.label}</span><div className="report-track"><i style={{width:`${appointments.length?count/appointments.length*100:0}%`}}/></div><strong>{count}</strong></div>;})}</div><h3 className="report-subtitle">Trạng thái lượt khám</h3><div className="status-bars">{(["waiting","examining","completed"] as const).map(key=>{const count=d.visits.filter(v=>v.status===key&&appointments.some(a=>a.id===v.appointmentId)).length;const total=d.visits.filter(v=>appointments.some(a=>a.id===v.appointmentId)).length;return <div key={key}><span className={`badge ${statuses[key].class}`}>{statuses[key].label}</span><div className="report-track"><i style={{width:`${total?count/total*100:0}%`}}/></div><strong>{count}</strong></div>;})}</div></section><section className="card"><div className="card-heading"><h2>Theo chuyên khoa</h2></div><div className="specialty-report">{d.specialties.map(sp=>{const count=appointments.filter(a=>{const sh=d.shifts.find(s=>s.id===a.shiftId);return d.doctors.find(doc=>doc.id===sh?.doctorId)?.specialtyId===sp.id;}).length;return <div key={sp.id}><span className="stat-icon mint"><Building2 size={19}/></span><strong>{sp.name}</strong><b>{count}</b><small>lịch hẹn</small></div>;})}</div></section></div></>;}
